private boolean isExponentiation(OpExpr expr) {
    FunctionalRef ref = expr.getOp();

    IdOrOp name = ref.getOriginalName();
    if (!(name instanceof Op)) return false;
    else return (((Op) name).getText().equals("^") || OprUtil.isPostfix((Op) name));
}


